153	/** Puts the inn's pieces together and runs the HTTP server. */
154	public final class Hotel {
155	
156	    private final Javalin server;
157	
158	    public Hotel(DataSource dataSource) {
159	        Rooms rooms = new Rooms(dataSource);
160	        ReservationStore store = new ReservationStore(dataSource);
161	        SentMessages sentMessages = new SentMessages(dataSource);
162	        ReservationService reservations =
163	                new ReservationService(rooms, store, new PriceCalculator(), new EmailSender(sentMessages));
164	        HttpApi api = new HttpApi(
165	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
166	        this.server = api.server();
167	    }
168	
169	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
170	    public int start(int port) {
171	        server.start(port);
172	        return server.port();
173	    }
174	
175	    public void stop() {
176	        server.stop();
177	    }
178	
179	    public static void main(String[] args) {
180	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
181	        Database database = new Database(System.getenv());
182	        new Hotel(database.dataSource()).start(port);
183	    }
184	}
185	package hotel.documents;
186	
187	import hotel.reservations.Reservation;
188	import hotel.rooms.Room;
189	import hotel.rooms.RoomType;
190	import java.math.BigDecimal;
191	import java.time.LocalDate;
192	
193	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
194	public record ReservationReceipt(
195	        String title,
196	        long reservationId,
197	        String guestName,
198	        String guestCpf,
199	        int roomNumber,
200	        RoomType roomType,
201	        LocalDate checkIn,
202	        LocalDate checkOut,
203	        int nights,
204	        BigDecimal subtotal,
205	        BigDecimal discount,
206	        BigDecimal total) {
207	
208	    public ReservationReceipt(Reservation reservation, Room room) {
209	        this(
210	                "Comprovante de reserva",
211	                reservation.id(),
212	                reservation.guest().name(),
213	                reservation.guest().cpf(),
214	                room.number(),
215	                room.type(),
216	                reservation.checkIn(),
217	                reservation.checkOut(),
218	                reservation.price().nights(),
219	                reservation.price().subtotal(),
220	                reservation.price().discount(),
221	                reservation.price().total());
222	    }
223	
224	    public String text() {
225	        StringBuilder text = new StringBuilder();
226	        text.append(title).append(" nº ").append(reservationId).append('\n');
227	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
228	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
229	        text.append("Entrada: ").append(TextFormat.date(checkIn))
230	                .append(" | Saída: ").append(TextFormat.date(checkOut))
231	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
232	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
233	        if (discount.signum() > 0) {
234	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
235	        }
236	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
237	        return text.toString();
238	    }
239	}
240	package hotel.documents;
241	
242	import java.math.BigDecimal;
243	import java.time.LocalDate;
244	import java.time.format.DateTimeFormatter;
245	import java.util.Locale;
246	
247	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
248	public final class TextFormat {
249	
250	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
251	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
252	
253	    private TextFormat() {
254	    }
255	
256	    public static String money(BigDecimal amount) {
257	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
258	    }
259	
260	    public static String date(LocalDate date) {
261	        return BRAZILIAN_DATE.format(date);
262	    }
263	}

