179	/**
180	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
181	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
182	 * (half-even) at every step.
183	 */
184	public final class PriceCalculator {
185	
186	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
187	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
188	
189	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
190	        int nights = 0;
191	        BigDecimal subtotal = cents(BigDecimal.ZERO);
192	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
193	            subtotal = subtotal.add(nightPrice(room, night));
194	            nights++;
195	        }
196	        BigDecimal discount = switch (ratePlan) {
197	            case STANDARD -> cents(BigDecimal.ZERO);
198	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
199	        };
200	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
201	    }
202	
203	    BigDecimal nightPrice(Room room, LocalDate night) {
204	        BigDecimal nightlyRate = room.nightlyRate();
205	        if (isHighSeason(night)) {
206	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
207	        }
208	        return cents(nightlyRate);
209	    }
210	
211	    /** High season: from December 15 to the end of February, and the whole of July. */
212	    static boolean isHighSeason(LocalDate date) {
213	        Month month = date.getMonth();
214	        return month == Month.JANUARY
215	                || month == Month.FEBRUARY
216	                || month == Month.JULY
217	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
218	    }
219	
220	    static BigDecimal cents(BigDecimal value) {
221	        return value.setScale(2, RoundingMode.HALF_EVEN);
222	    }
223	}

